// ResutoStudio: websites, sections, domains, creative.
// Owner: Agent F (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { idempotencyKey, uuid } from './common';

export const studioContractsVersion = 2 as const;

export const WEBSITE_TEMPLATES = ['olive', 'smash', 'minimal'] as const;
export type WebsiteTemplate = (typeof WEBSITE_TEMPLATES)[number];

export const SECTION_KINDS = [
  'hero', 'about', 'menu_highlights', 'gallery', 'reservations', 'ordering', 'location', 'hours', 'testimonials', 'contact', 'custom',
] as const;
export type SectionKind = (typeof SECTION_KINDS)[number];

const hex = z.string().regex(/^#[0-9a-fA-F]{6}$/, 'a colour like #173f36');

/** Copy in both site languages. Either may be empty; the site falls back to the other. */
export const studioText = (max: number) =>
  z.object({ en: z.string().trim().max(max).optional(), ar: z.string().trim().max(max).optional() }).strict();
export type LocalizedText = { en?: string; ar?: string };

export const websiteTheme = z.object({
  primaryColor: hex.optional(),
  accentColor: hex.optional(),
  backgroundColor: hex.optional(),
  logoMediaId: uuid.nullable().optional(),
  heroMediaId: uuid.nullable().optional(),
  font: z.enum(['manrope', 'editorial']).optional(),
}).strict();
export type WebsiteTheme = z.infer<typeof websiteTheme>;

export const websiteSeo = z.object({
  title: studioText(70).optional(),
  description: studioText(170).optional(),
  ogMediaId: uuid.nullable().optional(),
}).strict();
export type WebsiteSeo = z.infer<typeof websiteSeo>;

export const updateWebsite = z.object({
  template: z.enum(WEBSITE_TEMPLATES).optional(),
  theme: websiteTheme.optional(),
  seo: websiteSeo.optional(),
}).strict();
export type UpdateWebsite = z.infer<typeof updateWebsite>;

export const sectionContent = z.object({
  eyebrow: studioText(60).optional(),
  headline: studioText(140).optional(),
  body: studioText(2000).optional(),
  ctaLabel: studioText(40).optional(),
  mediaId: uuid.nullable().optional(),
  mediaIds: z.array(uuid).max(24).optional(),
  productIds: z.array(uuid).max(12).optional(),
  items: z.array(z.object({ title: studioText(120), body: studioText(600).optional() }).strict()).max(12).optional(),
}).strict();
export type SectionContent = z.infer<typeof sectionContent>;

export const createSection = z.object({
  kind: z.enum(SECTION_KINDS),
  content: sectionContent.default({}),
  isVisible: z.boolean().default(true),
}).strict();
export type CreateSection = z.infer<typeof createSection>;

export const updateSection = z.object({
  content: sectionContent.optional(),
  isVisible: z.boolean().optional(),
}).strict();
export type UpdateSection = z.infer<typeof updateSection>;

export const reorderSections = z.object({ ids: z.array(uuid).min(1).max(50) }).strict();

export const publishWebsite = z.object({ key: idempotencyKey, note: z.string().trim().max(200).optional() }).strict();

export const updateMedia = z.object({ alt: z.string().trim().max(200).nullable().optional(), altAr: z.string().trim().max(200).nullable().optional() }).strict();

// --- Custom domains ---------------------------------------------------------
export const domainHostname = z.string().trim().toLowerCase()
  .max(253)
  .regex(/^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/, 'a domain such as www.example.com');
export const addDomain = z.object({ hostname: domainHostname }).strict();

export const DOMAIN_STATUSES = ['pending_verification', 'verified', 'provisioning', 'active', 'failed', 'removed'] as const;
export type DomainStatus = (typeof DOMAIN_STATUSES)[number];

export interface DnsRecordInstruction {
  type: 'TXT' | 'CNAME' | 'A';
  name: string;
  value: string;
  purpose: 'ownership' | 'routing';
}

export interface CustomDomainView {
  id: string;
  hostname: string;
  status: DomainStatus;
  sslStatus: 'pending' | 'issued' | 'failed' | 'not_applicable';
  provider: 'vercel' | 'manual';
  providerReadiness: 'implemented_unverified' | 'manual';
  verificationRecord: DnsRecordInstruction;
  routingRecords: DnsRecordInstruction[];
  instructions: string[];
  lastCheckedAt: string | null;
  verifiedAt: string | null;
  lastError: string | null;
  createdAt: string;
}

// --- Creative ---------------------------------------------------------------
export const CREATIVE_KINDS = ['caption', 'post', 'menu_description', 'website_copy'] as const;
export const generateCreative = z.object({
  kind: z.enum(CREATIVE_KINDS),
  locale: z.enum(['en', 'ar']),
  brief: z.string().trim().min(3).max(600),
  productId: uuid.optional(),
  tone: z.enum(['warm', 'playful', 'premium', 'direct']).default('warm'),
  variants: z.number().int().min(1).max(3).default(2),
}).strict();
export type GenerateCreative = z.infer<typeof generateCreative>;

export const reviewCreative = z.object({ status: z.enum(['approved', 'rejected', 'used']) }).strict();

export interface CreativeAsset {
  id: string;
  kind: string;
  locale: 'en' | 'ar';
  prompt: string;
  output: { variants: Array<{ title?: string; text: string; hashtags?: string[] }>; fallbackReason?: string };
  provider: string;
  model: string | null;
  isFallback: boolean;
  status: 'draft' | 'approved' | 'rejected' | 'used';
  createdAt: string;
}

// --- Public site ------------------------------------------------------------
export interface PublicSiteSection {
  id: string;
  kind: SectionKind;
  content: SectionContent & { media?: { url: string; alt: string | null } | null; gallery?: Array<{ url: string; alt: string | null }> };
}

export interface PublicSite {
  slug: string;
  revision: number;
  publishedAt: string | null;
  preview: boolean;
  org: { name: string; nameAr: string | null; currency: string; country: string; defaultLocale: 'en' | 'ar' };
  template: WebsiteTemplate;
  theme: { primaryColor: string; accentColor: string; backgroundColor: string; font: 'manrope' | 'editorial'; logoUrl: string | null; heroUrl: string | null };
  seo: { title: LocalizedText; description: LocalizedText; ogImageUrl: string | null };
  sections: PublicSiteSection[];
  branches: Array<{
    id: string; code: string; name: string; nameAr: string | null; address: string | null; city: string | null; phone: string | null;
    latitude: number | null; longitude: number | null; openingHours: unknown;
    acceptsDineIn: boolean; acceptsPickup: boolean; acceptsDelivery: boolean; acceptsReservations: boolean;
  }>;
  menuHighlights: Array<{
    id: string; name: string; nameAr: string | null; description: string | null; descriptionAr: string | null;
    priceMinor: number; currency: string; imageUrl: string | null; dietary: string[];
  }>;
  canonicalHost: string | null;
  links: { reserve: string; order: string; site: string };
}
